"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[1599],{51599:e=>{e.exports=JSON.parse('{"eyebrow":"New in Salat-e-Mustaqeem","lede":"Recite, and the page follows you. Each word lights in gold as you say it, and anything you skipped is waiting for you, softly marked, when you finish.","small":"Free. Works offline. Your voice never leaves your phone.","ctaAppStore":"Get it on the App Store","ctaPlay":"Get it on Google Play","mushafLabel":"A demonstration: Al-F\u0101ti\u1e25ah lights word by word as it is recited","status":{"listening":"Listening\u2026","recited":"Recited","review":"Ayah {{n}}: <b>1 word to review</b>","well":"Ayah {{n}} \xb7 <b>well recited</b>"},"how":{"kicker":"How it works","h2":"Three moments, and nothing between you and the Quran","sub":"Tasm\u012b\u02bf is the word a hifz teacher uses for \u201crecite it back to me\u201d. It listens the way a patient teacher does: it follows, it notices, and it waits.","recite":{"h3":"Recite","p":"Open any ayah in the reader, or a Hifz lesson, and tap the lamp. Recite at your own pace, the way you would to your teacher."},"follows":{"h3":"The page follows","p":"The word you are saying glows. The page turns by itself. When the ayah ends, you see what to review: a soft wave under a skipped word, amber under one said differently."},"hear":{"h3":"Hear the word","p":"Tap a marked word and hear just that word from the qari\u2019s own recitation. Then recite the ayah again. No scores, ever: only \u201c2 words to review\u201d.","youSaid":"You said","ayahSays":"The ayah says"}},"hifz":{"kicker":"For hifz","h2":"Test me: the page stays veiled until you say it","sub":"From any Hifz lesson, turn on Test me. The ayah is hidden, and each word is revealed only as you recite it correctly. It is the closest thing to sitting before your teacher, at any hour of the night.","veilLabel":"Test me: words revealed as they are recited"},"muallim":{"kicker":"Coming next","chip":"Experimental","h2":"The Mu\u02bfallim: tajweed, held to your own pace","sub1":"A small listening model we are building ourselves, on the phone like the rest of Tasm\u012b\u02bf. It times each madd and ghunnah in \u1e25arak\u0101t measured from your own recitation, so a slow murattal and a quick \u1e25adr are judged alike, and it marks the places a teacher would pencil in.","sub2":"It begins with madd and ghunnah, then qalqalah. When it is unsure, it says nothing: a correct recitation should never be marked wrong. It will not replace your teacher; it helps you arrive prepared.","label":"The Mu\u02bfallim marks a madd held for two counts where four to five are asked","cap":"Madd munfa\u1e63il: held <b>2</b>, asks <b>4\u20135</b>"},"promise":{"kicker":"Our promise","h2":"Your recitation is between you and Allah","items":[{"b":"On your phone","span":"Tasm\u012b\u02bf listens on the device itself. Your voice is never sent anywhere, not even to us."},{"b":"Never recorded","span":"Audio lives in memory for a moment and is gone. Nothing is saved."},{"b":"Works offline","span":"After a one-time 88 MB download, it works in airplane mode, in the masjid, anywhere."},{"b":"Free","span":"No subscription, no ads. Sadaqah jariyah, in sh\u0101\u02be All\u0101h."}]},"who":{"kicker":"Made for","h2":"Every reciter, at every stage","cards":[{"h3":"Hifz students","p":"Revise a lesson on your own, catch the word that slips, and come to class ready."},{"h3":"Children","p":"Big gold words, gentle marks, no scores. Soon: the Qaida, letter by letter, from Alif to Y\u0101."},{"h3":"New learners","p":"Reciting alone is daunting. Tasm\u012b\u02bf walks beside you, ayah by ayah, at your pace."}],"tag":"Qaida coming soon"},"honest":{"h3":"It checks words, not tajweed","p":"Tasm\u012b\u02bf tells you whether you said the right words in the right order. It does not judge makharij, madd or other rules of tajweed, and it is not a teacher. Please recite to a teacher too. Tasm\u012b\u02bf is marked Experimental while we keep improving it."},"faq":{"kicker":"Questions","h2":"Before you begin","items":[{"q":"Is my recitation recorded or uploaded?","a":"No. Listening happens entirely on your phone. Audio is never stored and never sent, to us or anyone."},{"q":"Does it work without the internet?","a":"Yes, once the 88 MB listening pack is on your phone. It downloads on Wi\u2011Fi by default; you can choose mobile data."},{"q":"Which phones does it work on?","a":"iPhone and Android phones that run Salat-e-Mustaqeem. On older phones it adjusts itself so the gold light keeps up."},{"q":"Can it check my tajweed?","a":"Not yet, but the Mu\u02bfallim is on its way. It will start with the lengths of madd and ghunnah, measured against your own pace, and stay silent whenever it is unsure. Until then, please recite to a teacher for tajweed."},{"q":"Is it good for children?","a":"Yes. There are no scores, only gentle marks. A Qaida mode for learning the letters is on its way."}]},"final":{"cite":"\u201cAnd recite the Quran with measured recitation.\u201d Al-Muzzammil 73:4","h2":"Begin with one ayah tonight"},"credit":"Tasm\u012b\u02bf\u2019s speech model is \u201ctilawi-fastconformer-quran\u201d by muhdur, licensed CC BY 4.0, fine-tuned from NVIDIA\u2019s Arabic FastConformer (CC BY 4.0). Quran text: Tanzil."}')}}]);